artifacts.solve_py:
#!/usr/bin/env python3
import csv
import json
import math
import os
import sys
from pyscipopt import Model, quicksum

DATA = "/app/data"
OUT = "/app/submissions/solution.csv"

def read_csv(name):
    with open(os.path.join(DATA, name), newline="") as f:
        return list(csv.DictReader(f))

def main():
    cfg = json.load(open(os.path.join(DATA, "config.json")))
    slots = read_csv("time_slots.csv")
    classes = read_csv("truck_classes.csv")
    blocks = read_csv("yard_blocks.csv")
    elig = read_csv("class_block_eligibility.csv")
    scenarios = read_csv("scenarios.csv")
    demand = read_csv("scenario_demand.csv")
    capmult = read_csv("scenario_block_capacity.csv")
    mixlim = read_csv("slot_class_mix_limits.csv")
    pools = read_csv("team_pool_limits.csv")
    commits = read_csv("scenario_service_commitments.csv")

    T = [r["slot_id"] for r in slots]
    Tidx = {r["slot_id"]: int(r["slot_index"]) for r in slots}
    slot_order = sorted(T, key=lambda t: Tidx[t])
    gatecap = {r["slot_id"]: int(r["base_gate_capacity"]) for r in slots}
    queuelim = {r["slot_id"]: int(r["queue_limit_trucks"]) for r in slots}
    reeferlim = {r["slot_id"]: int(r["reefer_inspection_limit"]) for r in slots}
    expcap = {r["slot_id"]: float(r["drayage_exposure_cap"]) for r in slots}
    minquota = {r["slot_id"]: int(r["min_quota"]) for r in slots}

    C = [r["class_id"] for r in classes]
    Cinfo = {}
    for r in classes:
        c = r["class_id"]
        Cinfo[c] = {
            "shortage": float(r["shortage_penalty"]),
            "wait": float(r["waiting_cost_per_slot"]),
            "exposure": float(r["exposure_units"]),
            "reefer": r["reefer_flag"] == "1",
            "latest": int(r["latest_service_slot"]),
            "allowed": set(r["allowed_slots"].split("|")),
            "cutoff": r["cutoff_zero_queue"] == "1",
        }

    B = [r["block_id"] for r in blocks]
    Binfo = {}
    for r in blocks:
        b = r["block_id"]
        Binfo[b] = {
            "base": float(r["base_work_units"]),
            "maxteam": int(r["max_extra_teams"]),
        }

    # eligibility: list of (c, b, work, cost)
    E = []
    Eset = set()
    for r in elig:
        c, b = r["class_id"], r["block_id"]
        E.append((c, b, float(r["work_units"]), float(r["handling_cost"])))
        Eset.add((c, b))
    work = {(r["class_id"], r["block_id"]): float(r["work_units"]) for r in elig}
    hcost = {(r["class_id"], r["block_id"]): float(r["handling_cost"]) for r in elig}

    W = [r["scenario_id"] for r in scenarios]
    prob = {r["scenario_id"]: float(r["probability"]) for r in scenarios}
    gmult = {r["scenario_id"]: float(r["gate_multiplier"]) for r in scenarios}

    D = {}
    for r in demand:
        D[(r["scenario_id"], r["slot_id"], r["class_id"])] = int(r["requested_trucks"])
    M = {}
    for r in capmult:
        M[(r["scenario_id"], r["slot_id"], r["block_id"])] = float(r["capacity_multiplier"])

    # shared lane rules per slot: list of (classes, cap)
    lanes = {}
    for r in mixlim:
        lanes.setdefault(r["slot_id"], []).append((r["classes"].split("|"), int(r["max_admissions"])))

    # pools per slot: list of (blocks, cap)
    poolcaps = {}
    for r in pools:
        poolcaps.setdefault(r["slot_id"], []).append((r["blocks"].split("|"), int(r["max_extra_teams"])))

    # commitments: (w, c, by_slot, min)
    CM = [(r["scenario_id"], r["class_id"], r["by_slot_id"], int(r["min_served_trucks"])) for r in commits]

    alpha_q = cfg["quota_admin_cost"]
    beta_e = cfg["extra_team_cost"]
    gamma = cfg["team_work_unit_gain"]
    day_lo = cfg["minimum_total_quota"]
    day_hi = cfg["maximum_total_quota"]
    ramp = cfg["quota_ramp_limit"]
    maxteams_slot = cfg["max_extra_teams_per_slot"]
    tail_w = cfg["tail_risk_weight"]
    tail_a = cfg["tail_risk_alpha"]

    # prefixes per slot
    prefix = {}
    for i, t in enumerate(slot_order):
        prefix[t] = slot_order[: i + 1]

    model = Model("gate_dro")
    model.setParam("gaprel", 0.0005)
    time_limit = 300.0
    env = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
    if env is not None:
        try:
            time_limit = min(time_limit, float(env))
        except ValueError:
            pass
    model.setParam("limits/time", time_limit)

    # ---------------- variables ----------------
    q = {}
    for t in slot_order:
        for c in C:
            if t in Cinfo[c]["allowed"]:
                ub = minquota[t] + 200  # generous
                q[(t, c)] = model.addVar(name=f"q_{t}_{c}", vtype="I", lb=0, ub=ub, obj=0.0)

    e = {}
    for t in slot_order:
        for b in B:
            e[(t, b)] = model.addVar(name=f"e_{t}_{b}", vtype="I", lb=0, ub=Binfo[b]["maxteam"], obj=0.0)

    a = {}
    s = {}
    for w in W:
        for t in slot_order:
            for c in C:
                d = D.get((w, t, c), 0)
                if t in Cinfo[c]["allowed"] and d > 0:
                    a[(w, t, c)] = model.addVar(name=f"a_{w}_{t}_{c}", vtype="I", lb=0, ub=d, obj=0.0)
        for t in slot_order:
            for (c, b, _, _) in E:
                if Tidx[t] <= Cinfo[c]["latest"]:
                    # upper bound: total demand of class in scenario up to t (approx by total)
                    tot = sum(D.get((w, tt, c), 0) for tt in slot_order)
                    if tot > 0:
                        s[(w, t, b, c)] = model.addVar(name=f"s_{w}_{t}_{b}_{c}", vtype="I", lb=0, ub=tot, obj=0.0)

    # ---------------- first-stage constraints ----------------
    for t in slot_order:
        model.addCons(
            quicksum(q[(t, c)] for c in C if (t, c) in q) >= minquota[t],
            name=f"minquota_{t}",
        )
    model.addCons(
        quicksum(q[k] for k in q) >= day_lo, name="day_lo"
    )
    model.addCons(
        quicksum(q[k] for k in q) <= day_hi, name="day_hi"
    )
    for i in range(1, len(slot_order)):
        t0, t1 = slot_order[i - 1], slot_order[i]
        for c in C:
            if (t0, c) in q and (t1, c) in q:
                model.addCons(
                    q[(t1, c)] - q[(t0, c)] <= ramp, name=f"ramp_p_{t1}_{c}"
                )
                model.addCons(
                    q[(t0, c)] - q[(t1, c)] <= ramp, name=f"ramp_n_{t1}_{c}"
                )
    for t in slot_order:
        model.addCons(
            quicksum(e[(t, b)] for b in B) <= maxteams_slot, name=f"teamslot_{t}"
        )
        for blist, cap in poolcaps.get(t, []):
            model.addCons(
                quicksum(e[(t, b)] for b in blist) <= cap, name=f"pool_{t}_{cap}"
            )

    # ---------------- second-stage constraints ----------------
    # Precompute per-scenario class block lists for service variables to avoid
    # repeated dict scans and to keep term lists ordinary Python lists.
    s_by_wtc = {}
    for (ww, tt, bb, cc), var in s.items():
        s_by_wtc.setdefault((ww, cc), {}).setdefault(tt, []).append((bb, var))

    # scenario cost terms
    scen_cost = {}
    for w in W:
        terms = []
        # handling
        for (ww, t, b, c), var in s.items():
            if ww == w:
                terms.append(hcost[(c, b)] * var)
        # shortage
        for (ww, t, c), var in a.items():
            if ww == w:
                d = D.get((w, t, c), 0)
                if d > 0:
                    terms.append(Cinfo[c]["shortage"] * (d - var))
        # waiting: queue per class per slot = cumA - cumS
        for c in C:
            cumA_terms = []
            cumS_terms = []
            for t in slot_order:
                if (w, t, c) in a:
                    cumA_terms.append(a[(w, t, c)])
                for (bb, var) in s_by_wtc.get((w, c), {}).get(t, []):
                    cumS_terms.append(var)
                wait_terms = []
                for v in cumA_terms:
                    wait_terms.append(v)
                for v in cumS_terms:
                    wait_terms.append(-v)
                if wait_terms:
                    terms.append(Cinfo[c]["wait"] * quicksum(wait_terms))
        if terms:
            scen_cost[w] = quicksum(terms)
        else:
            scen_cost[w] = 0.0

    # CVaR linearization
    z = model.addVar(name="cvar_z", vtype="C", lb=-1e9, ub=1e9, obj=0.0)
    u = {}
    for w in W:
        u[w] = model.addVar(name=f"cvar_u_{w}", vtype="C", lb=0, ub=1e9, obj=0.0)
        model.addCons(u[w] >= scen_cost[w] - z, name=f"cvar_link_{w}")

    cvar_expr_terms = [z]
    for w in W:
        cvar_expr_terms.append((prob[w] / (1.0 - tail_a)) * u[w])
    cvar_expr = quicksum(cvar_expr_terms) / (1.0 - tail_a)
    expected_terms = [prob[w] * scen_cost[w] for w in W]
    expected = quicksum(expected_terms)
    obj_terms = []
    for k in q:
        obj_terms.append(alpha_q * q[k])
    for k in e:
        obj_terms.append(beta_e * e[k])
    obj_terms.append(expected)
    obj_terms.append(tail_w * cvar_expr)
    obj_expr = quicksum(obj_terms)
    model.setObjective(obj_expr, sense="minimize")

    for w in W:
        # admit <= quota and <= demand
        for (ww, t, c), var in a.items():
            if ww == w:
                if (t, c) in q:
                    model.addCons(var <= q[(t, c)], name=f"admit_quota_{w}_{t}_{c}")
                d = D.get((w, t, c), 0)
                model.addCons(var <= d, name=f"admit_demand_{w}_{t}_{c}")
        # gate capacity
        for t in slot_order:
            vars_t = [a[(w, t, c)] for c in C if (w, t, c) in a]
            if vars_t:
                model.addCons(
                    quicksum(vars_t) <= math.floor(gmult[w] * gatecap[t]),
                    name=f"gate_{w}_{t}",
                )
        # reefer
        for t in slot_order:
            vars_t = [a[(w, t, c)] for c in C if (w, t, c) in a and Cinfo[c]["reefer"]]
            if vars_t:
                model.addCons(quicksum(vars_t) <= reeferlim[t], name=f"reefer_{w}_{t}")
        # exposure
        for t in slot_order:
            terms = [Cinfo[c]["exposure"] * a[(w, t, c)] for c in C if (w, t, c) in a]
            if terms:
                model.addCons(quicksum(terms) <= expcap[t], name=f"exposure_{w}_{t}")
        # lanes
        for t in slot_order:
            for clist, cap in lanes.get(t, []):
                terms = [a[(w, t, c)] for c in clist if (w, t, c) in a]
                if terms:
                    model.addCons(quicksum(terms) <= cap, name=f"lane_{w}_{t}_{cap}")
        # cumulative service <= cumulative admission
        for c in C:
            for t in slot_order:
                cumA_terms = [a[(w, tt, c)] for tt in prefix[t] if (w, tt, c) in a]
                cumS_terms = []
                for tt in prefix[t]:
                    for (bb, var) in s_by_wtc.get((w, c), {}).get(tt, []):
                        cumS_terms.append(var)
                lhs_terms = []
                for v in cumS_terms:
                    lhs_terms.append(v)
                for v in cumA_terms:
                    lhs_terms.append(-v)
                if lhs_terms:
                    model.addCons(quicksum(lhs_terms) <= 0, name=f"flow_{w}_{t}_{c}")
                else:
                    # no variables at all in this prefix; constraint is trivially 0<=0
                    pass
        # queue limit per class
        for c in C:
            for t in slot_order:
                cumA_terms = [a[(w, tt, c)] for tt in prefix[t] if (w, tt, c) in a]
                cumS_terms = []
                for tt in prefix[t]:
                    for (bb, var) in s_by_wtc.get((w, c), {}).get(tt, []):
                        cumS_terms.append(var)
                lhs_terms = []
                for v in cumA_terms:
                    lhs_terms.append(v)
                for v in cumS_terms:
                    lhs_terms.append(-v)
                if lhs_terms:
                    model.addCons(quicksum(lhs_terms) <= queuelim[t], name=f"queue_{w}_{t}_{c}")
        # cutoff zero queue
        for c in C:
            if Cinfo[c]["cutoff"]:
                tcut = Cinfo[c]["latest"]
                cut_slots = [tt for tt in slot_order if Tidx[tt] <= tcut]
                cumA_terms = [a[(w, tt, c)] for tt in cut_slots if (w, tt, c) in a]
                cumS_terms = []
                for tt in cut_slots:
                    for (bb, var) in s_by_wtc.get((w, c), {}).get(tt, []):
                        cumS_terms.append(var)
                lhs_terms = []
                for v in cumA_terms:
                    lhs_terms.append(v)
                for v in cumS_terms:
                    lhs_terms.append(-v)
                if lhs_terms:
                    model.addCons(quicksum(lhs_terms) == 0, name=f"cutoff_{w}_{c}")
        # all admitted served by end of day
        for c in C:
            totA_terms = [a[(w, t, c)] for t in slot_order if (w, t, c) in a]
            totS_terms = []
            for (bb, var) in s_by_wtc.get((w, c), {}):
                pass
            for tt in slot_order:
                for (bb, var) in s_by_wtc.get((w, c), {}).get(tt, []):
                    totS_terms.append(var)
            lhs_terms = []
            for v in totS_terms:
                lhs_terms.append(v)
            for v in totA_terms:
                lhs_terms.append(-v)
            if lhs_terms:
                model.addCons(quicksum(lhs_terms) == 0, name=f"serveall_{w}_{c}")
        # commitments
        for (ww, c, tby, mn) in CM:
            if ww == w:
                by_slots = [tt for tt in slot_order if Tidx[tt] <= Tidx[tby]]
                cumS_terms = []
                for tt in by_slots:
                    for (bb, var) in s_by_wtc.get((w, c), {}).get(tt, []):
                        cumS_terms.append(var)
                if cumS_terms:
                    model.addCons(quicksum(cumS_terms) >= mn, name=f"commit_{w}_{c}_{tby}")
                else:
                    model.addCons(0 >= mn, name=f"commit_{w}_{c}_{tby}")
        # block capacity
        for t in slot_order:
            for b in B:
                terms = []
                # build from all classes served at (w,t,b)
                for cc in C:
                    for (bb, var) in s_by_wtc.get((w, cc), {}).get(t, []):
                        if bb == b:
                            terms.append(work[(cc, b)] * var)
                if terms:
                    model.addCons(
                        quicksum(terms) <= M[(w, t, b)] * Binfo[b]["base"] + gamma * e[(t, b)],
                        name=f"cap_{w}_{t}_{b}",
                    )

    model.optimize()
    status = model.getStatus()
    print("STATUS:", status)
    nsols = model.getNSols()
    print("NSOLS:", nsols)
    objval = None
    if nsols > 0:
        if model.getBestSol() is not None:
            objval = model.getObjVal()
            print("OBJ:", objval)

    # extract
    qv = {}
    ev = {}
    av = {}
    sv = {}
    if nsols > 0 and model.getBestSol() is not None:
        for k, var in q.items():
            qv[k] = int(round(model.getVal(var)))
        for k, var in e.items():
            ev[k] = int(round(model.getVal(var)))
        for k, var in a.items():
            av[k] = int(round(model.getVal(var)))
        for k, var in s.items():
            sv[k] = int(round(model.getVal(var)))
    else:
        print("NO SOLUTION FOUND - writing empty solution")

    # validation
    ok = True
    def check(cond, msg):
        nonlocal ok
        if not cond:
            ok = False
            print("VIOLATION:", msg)

    # quota validation
    for t in slot_order:
        tot = sum(qv.get((t, c), 0) for c in C)
        check(tot >= minquota[t], f"minquota {t}: {tot}")
        for c in C:
            if (t, c) not in q:
                check(qv.get((t, c), 0) == 0, f"quota window {t} {c}")
    daytot = sum(qv.values())
    check(day_lo <= daytot <= day_hi, f"day quota {daytot}")
    for i in range(1, len(slot_order)):
        t0, t1 = slot_order[i - 1], slot_order[i]
        for c in C:
            check(abs(qv.get((t1, c), 0) - qv.get((t0, c), 0)) <= ramp, f"ramp {t1} {c}")
    for t in slot_order:
        check(sum(ev.get((t, b), 0) for b in B) <= maxteams_slot, f"teamslot {t}")
        for blist, cap in poolcaps.get(t, []):
            check(sum(ev.get((t, b), 0) for b in blist) <= cap, f"pool {t}")
    for (t, b), v in ev.items():
        check(v <= Binfo[b]["maxteam"], f"team block {t} {b}")

    for w in W:
        for t in slot_order:
            tot = sum(av.get((w, t, c), 0) for c in C)
            check(tot <= math.floor(gmult[w] * gatecap[t]), f"gate {w} {t}")
            ree = sum(av.get((w, t, c), 0) for c in C if Cinfo[c]["reefer"])
            check(ree <= reeferlim[t], f"reefer {w} {t}")
            exp = sum(Cinfo[c]["exposure"] * av.get((w, t, c), 0) for c in C)
            check(exp <= expcap[t] + 1e-6, f"exposure {w} {t}")
            for clist, cap in lanes.get(t, []):
                check(sum(av.get((w, t, c), 0) for c in clist) <= cap, f"lane {w} {t}")
            for c in C:
                v = av.get((w, t, c), 0)
                check(v <= qv.get((t, c), 0), f"admit quota {w} {t} {c}")
                check(v <= D.get((w, t, c), 0), f"admit demand {w} {t} {c}")
        for c in C:
            cumA = 0
            cumS = 0
            for t in slot_order:
                cumA += av.get((w, t, c), 0)
                cumS += sum(sv.get((w, t, b, c), 0) for b in B)
                check(cumS <= cumA, f"flow {w} {t} {c}")
                check(cumA - cumS <= queuelim[t], f"queue {w} {t} {c}")
            if Cinfo[c]["cutoff"]:
                tcut = Cinfo[c]["latest"]
                cA = sum(av.get((w, tt, c), 0) for tt in prefix[tcut])
                cS = sum(sv.get((w, tt, b, c), 0) for tt in prefix[tcut] for b in B)
                check(cA == cS, f"cutoff {w} {c}")
            totA = sum(av.get((w, t, c), 0) for t in slot_order)
            totS = sum(sv.get((w, t, b, c), 0) for t in slot_order for b in B)
            check(totS == totA, f"serveall {w} {c}")
        for (ww, c, tby, mn) in CM:
            if ww == w:
                cS = sum(sv.get((w, tt, b, c), 0) for tt in prefix[tby] for b in B)
                check(cS >= mn, f"commit {w} {c}")
        for t in slot_order:
            for b in B:
                used = sum(work[(c, b)] * sv.get((w, t, b, c), 0) for (c, bb, _, _) in E if bb == b)
                capv = M[(w, t, b)] * Binfo[b]["base"] + gamma * ev.get((t, b), 0)
                check(used <= capv + 1e-6, f"cap {w} {t} {b}")

    print("VALIDATION:", "OK" if ok else "FAILED")

    # write solution
    rows = []
    for t in slot_order:
        for c in C:
            v = qv.get((t, c), 0)
            if v > 0:
                rows.append(["quota", "", t, c, "", str(v)])
    for t in slot_order:
        for b in B:
            v = ev.get((t, b), 0)
            if v > 0:
                rows.append(["team", "", t, "", b, str(v)])
    for w in W:
        for t in slot_order:
            for c in C:
                v = av.get((w, t, c), 0)
                if v > 0:
                    rows.append(["admit", w, t, c, "", str(v)])
    for w in W:
        for t in slot_order:
            for (c, b, _, _) in E:
                v = sv.get((w, t, b, c), 0)
                if v > 0:
                    rows.append(["service", w, t, c, b, str(v)])

    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    with open(OUT, "w", newline="") as f:
        wtr = csv.writer(f)
        wtr.writerow(["row_type", "scenario_id", "slot_id", "class_id", "block_id", "value"])
        wtr.writerows(rows)
    print("WROTE", OUT, "rows:", len(rows))
    if not ok:
        print("WARNING: validation failed but file written (best effort)")

if __name__ == "__main__":
    main()
